WITH p AS (SELECT coalesce(%s::text,'') ma_khuon,coalesce(%s::text,'') ma_vt,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR(coalesce(u.ds_branchs,'')='' AND coalesce(u.ds_stocks,'')='') unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid),d AS (SELECT ma_vt,sum(so_luong) nhu_cau_tuong_lai FROM public.mfkhsx_po_fc WHERE ngay_giao_hang>=current_date AND nguon_du_lieu IN('FC','SO') GROUP BY ma_vt) SELECT h.ma_khuon,sp.ma_sp,h.tong_so_shot,h.so_shot_bh,coalesce(h.so_shot_bh,0)-coalesce(h.tong_so_shot,0) shot_con_lai,coalesce(d.nhu_cau_tuong_lai,0) nhu_cau_tuong_lai,count(*) OVER() total FROM public.dmhosokhuon h JOIN public.dmhosokhuonsp sp ON sp.ma_khuon=h.ma_khuon CROSS JOIN s LEFT JOIN d ON d.ma_vt=sp.ma_sp WHERE s.ok IS NOT NULL AND(s.unrestricted OR s.bs='')AND(s.ma_khuon='' OR h.ma_khuon=ANY(string_to_array(s.ma_khuon,',')))AND(s.ma_vt='' OR sp.ma_sp=ANY(string_to_array(s.ma_vt,','))) ORDER BY h.ma_khuon,sp.ma_sp LIMIT(SELECT lim FROM p);
